/**
 * none = no account yet; pending = account exists but onboarding
not finished or under review; active = charges + payouts both
enabled; restricted = Stripe has explicitly disabled the account.

 */
export type StripeConnectAccountResponseStatus =
  (typeof StripeConnectAccountResponseStatus)[keyof typeof StripeConnectAccountResponseStatus];

export const StripeConnectAccountResponseStatus = {
  none: "none",
  pending: "pending",
  active: "active",
  restricted: "restricted",
} as const;

/**
 * Snapshot of the SP's Stripe Connect Express account. `accountId` is
null only when the SP has never started onboarding. `status` collapses
Stripe's many flags into the four states the mobile UI cares about.

 */
export interface StripeConnectAccountResponse {
  /** Stripe `acct_…` id, or null if onboarding never started. */
  accountId: string | null;
  /** none = no account yet; pending = account exists but onboarding
not finished or under review; active = charges + payouts both
enabled; restricted = Stripe has explicitly disabled the account.
 */
  status: StripeConnectAccountResponseStatus;
  /** Mirror of `account.charges_enabled` from Stripe. */
  chargesEnabled: boolean;
  /** Mirror of `account.payouts_enabled` from Stripe. */
  payoutsEnabled: boolean;
  /** Stripe `requirements.currently_due` field; empty when none. */
  requirementsDue: string[];
}

/**
 * Aggregated money for one window. All amounts are integer USD cents.
 */
export interface EarningsBucket {
  /** SUM(price) cents — what the SP earned before the platform cut. */
  gross: number;
  /** SUM(platform_fee) cents — what the platform kept. */
  fees: number;
  /** SUM(price) cents for bookings that were refunded back to the customer. */
  refunded: number;
  /** gross - fees - refunded */
  net: number;
  /** Number of paid bookings in this window. */
  count: number;
}

/**
 * Live Stripe Connect balance for the SP's connected account.
 */
export interface EarningsBalance {
  /** Funds still in Stripe's pending bucket awaiting payout. */
  pendingCents: number;
  /** Funds Stripe could pay out today. */
  availableCents: number;
  /** ISO currency code */
  currency: string;
}

/**
 * One row in the SP's recent-payments list.
 */
export interface EarningsRecentItem {
  bookingId: string;
  customerName: string;
  serviceTitle: string;
  /** YYYY-MM-DD */
  scheduledDate: string;
  grossCents: number;
  feeCents: number;
  /** 0 if the booking was refunded. */
  netCents: number;
  refunded: boolean;
  /** When the booking row (and its PaymentIntent) was created. */
  paidAt: string;
}

/**
 * Full SP earnings dashboard payload.
 */
export interface EarningsResponse {
  /** Always "usd" for v1. */
  currency: string;
  lifetime: EarningsBucket;
  last30Days: EarningsBucket;
  /** Null when SP hasn't finished Connect onboarding or Stripe is briefly unreachable. */
  balance: EarningsBalance | null;
  recentPayments: EarningsRecentItem[];
}

export type MessageSenderRole =
  (typeof MessageSenderRole)[keyof typeof MessageSenderRole];

export const MessageSenderRole = {
  customer: "customer",
  business: "business",
} as const;

/**
 * One chat message on a per-booking thread.
 */
export interface Message {
  id: string;
  bookingId: string;
  senderUserId: string;
  senderRole: MessageSenderRole;
  body: string;
  /** Set when the OTHER party first opens the thread after this message arrived. */
  readAt?: string | null;
  createdAt: string;
}

export interface SendMessageRequest {
  /**
   * The message text. Trimmed server-side; max 2000 chars after trim.
   * @minLength 1
   * @maxLength 2000
   */
  body: string;
}

/**
 * One row in the caller's inbox — the latest activity per booking thread.
 */
export interface Conversation {
  bookingId: string;
  /** If caller is the customer, this is the business's name; if caller is the SP, the customer's name. */
  counterpartyName: string;
  /** YYYY-MM-DD */
  scheduledDate: string;
  lastMessageBody: string;
  lastMessageAt: string;
  /** True when the caller authored the most-recent message. */
  lastMessageFromMe: boolean;
  /** Number of unread messages from the other side. */
  unreadCount: number;
}

/**
 * One-shot Stripe Account Link URL for the hosted Express onboarding flow.
 */
export interface StripeConnectOnboardingLinkResponse {
  /** Hosted Stripe URL the mobile client opens via WebBrowser. */
  url: string;
  /** ISO timestamp at which the URL stops working (~5 min from creation). */
  expiresAt: string;
}

